window.kbPageData["views/entry/k-1a461246c93f981d"] = {"key":"entry/k-1a461246c93f981d","state":{"route":"entry/k-1a461246c93f981d"},"node":{"id":"k-1a461246c93f981d","mode":"k","title":"独立自主的和平外交政策","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["open"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"1.独立自主的和平外交政策\n中国始终坚持维护世界和平、促进共同发展的外交政策宗旨，致力于推动构建人类命运\n共同体。\n中国坚定奉行独立自主的和平外交政策，始终根据事情本身的是非曲直决定自己的立场\n和政策，维护国际关系基本准则，维护国际公平正义。\n中国坚持在和平共处五项原则基础上同各国发展友好合作，推动…","sources":[{"id":"a156952e65e40d9c","label":"独立自主的和平外交政策","topic":"发展与治理","category":"非时政","text":"1.独立自主的和平外交政策\n中国始终坚持维护世界和平、促进共同发展的外交政策宗旨，致力于推动构建人类命运\n共同体。\n中国坚定奉行独立自主的和平外交政策，始终根据事情本身的是非曲直决定自己的立场\n和政策，维护国际关系基本准则，维护国际公平正义。\n中国坚持在和平共处五项原则基础上同各国发展友好合作，推动构建新型国际关系，深\n化拓展平等、开放、合作的全球伙伴关系，致力于扩大同各国利益的汇合点。\n中国坚持对外开放的基本国策，坚定奉行互利共赢的开放战略，不断以中国新发展为世\n界提供新机遇，推动建设开放型世界经济，更好惠及各国人民。\n中国积极参与全球治理体系改革和建设，践行共商共建共享的全球治理观，坚持真正的\n多边主义，推进国际关系民主化，推动全球治理朝着更加公正合理的方向发展。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"open","title":"高水平开放与经贸规则"}],"units":{"k-1a461246c93f981d":[]}};
